import { useId, useRef, useState, type KeyboardEvent } from 'react';
import { JxButton } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  label?: string;
  placeholder?: string;
  defaultValue?: string[];
  maxTags?: number;
  onChange?: (tags: string[]) => void;
}

const SEPARATORS = [',', ';'];

export default function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  defaultValue = [],
  maxTags = 12,
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');
  const [error, setError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const inputId = useId();
  const hintId = useId();

  const isFull = tags.length >= maxTags;

  const apply = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const commit = (raw: string) => {
    const tag = raw.trim().replace(/\s+/g, ' ');
    if (!tag) return;
    if (isFull) {
      setError(`Максимум ${maxTags} тегов`);
      return;
    }
    if (tags.some((t) => t.toLowerCase() === tag.toLowerCase())) {
      setError(`Тег «${tag}» уже добавлен`);
      return;
    }
    setError(null);
    apply([...tags, tag]);
    setDraft('');
  };

  const remove = (tag: string) => {
    setError(null);
    apply(tags.filter((t) => t !== tag));
    inputRef.current?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || SEPARATORS.includes(event.key)) {
      event.preventDefault();
      commit(draft);
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      event.preventDefault();
      remove(tags[tags.length - 1]);
    }
  };

  return (
    <div
      className="jx-field"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}
    >
      <label className="jx-label" htmlFor={inputId}>
        {label}
      </label>

      <input
        id={inputId}
        ref={inputRef}
        className="jx-input"
        type="text"
        value={draft}
        placeholder={isFull ? `Достигнут лимит в ${maxTags} тегов` : placeholder}
        disabled={isFull}
        aria-describedby={hintId}
        aria-invalid={error ? true : undefined}
        onChange={(event) => {
          const raw = event.target.value;
          const separator = SEPARATORS.find((s) => raw.includes(s));
          if (separator) {
            commit(raw.slice(0, raw.indexOf(separator)));
            return;
          }
          setError(null);
          setDraft(raw);
        }}
        onKeyDown={handleKeyDown}
        onBlur={() => commit(draft)}
      />

      <p
        id={hintId}
        className={error ? 'jx-text jx-text--error' : 'jx-text jx-text--muted'}
        role={error ? 'alert' : undefined}
        style={{ margin: 0, fontSize: 'var(--jx-font-size-sm)' }}
      >
        {error ?? `Enter или запятая добавляют тег. ${tags.length} из ${maxTags}.`}
      </p>

      <ul
        aria-label="Выбранные теги"
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: 'var(--jx-space-2)',
          margin: 0,
          padding: 0,
          listStyle: 'none',
        }}
      >
        {tags.map((tag) => (
          <li
            key={tag}
            className="jx-tag"
            style={{ display: 'inline-flex', alignItems: 'center', gap: 'var(--jx-space-1)' }}
          >
            <span>{tag}</span>
            <JxButton
              type="button"
              variant="ghost"
              size="sm"
              aria-label={`Удалить тег ${tag}`}
              onClick={() => remove(tag)}
            >
              ×
            </JxButton>
          </li>
        ))}
      </ul>
    </div>
  );
}

